    if (!isPaid(b) && /^Yes/.test(app)) {
      const left = Math.round((due - today) / DAY);
      const hit = offsets.filter(o => left <= o);
      const stage = left < 0 ? `overdue:${Math.floor(-left / 7)}` : (hit.length ? String(Math.min(...hit)) : '');
      const rec = { b, v, app, due, left, out: outstanding(b), tax: taxOn(b), fyRisk: due <= fyEnd && acc >= fyStart, interest: left < 0 ? msmedInterest(outstanding(b), -left) : 0 };
      open.push(rec);
      if (stage && stage !== String(b.alert_stage)) {
        u.alert_stage = stage;
        if (stage !== '7') {
          const who = [v && v.finance_owner_slack_id ? `<@${v.finance_owner_slack_id}>` : null, (left <= 1) && s.slack_finance_head_id ? `<@${s.slack_finance_head_id}>` : null].filter(Boolean).join(' ');
          const head = left < 0 ? `🚨 *43B(h) limit crossed: ${-left} days overdue*` : left === 0 ? '🔴 *MSME payment due TODAY (43B(h))*' : `🟠 *MSME payment due in ${left} day${left > 1 ? 's' : ''}*`;
          slack(`${head} ${who}\n*${b.vendor_name}* (${v.msme_category}, Udyam ${v.udyam_number}${app.includes('unverified') ? ', ⚠️ unverified' : ''}) · bill *${b.bill_number}* dated ${fmt(parseDay(b.bill_date) || acc)}\n` +
