    open_bills: open.length, open_amount: Math.round(sum(open, 'out')),
    due_7_days: { count: wk.length, amount: Math.round(sum(wk, 'out')) },
    overdue: { count: over.length, amount: Math.round(sum(over, 'out')), tax_at_risk: Math.round(sum(over, 'tax')), est_interest: Math.round(sum(over, 'interest')) },
